+
+impl SpMotionPlan {
+    pub fn new(yaw_vel: f32, pitch_vel: f32, yaw_acc: f32, pitch_acc: f32,
+               max_yaw_acc: f32, max_pitch_acc: f32, valid_for: f32) -> Self {
+        Self { velocity: Vec2::new(yaw_vel,pitch_vel), acceleration: Vec2::new(yaw_acc,pitch_acc),
+               max_acceleration: Vec2::new(max_yaw_acc,max_pitch_acc), valid_for, elapsed: 0.0,
+               previous_rate: Vec2::ZERO }
+    }
+
+    fn sample(&self, initial: GimbalAimTarget) -> GimbalAimTarget {
+        let offset = self.velocity*self.elapsed + self.acceleration*(0.5*self.elapsed*self.elapsed);
+        GimbalAimTarget { yaw: initial.yaw+offset.x, pitch: initial.pitch+offset.y }
+    }
 }
